}
}
draw((0.5, 2.5)--(0.5, 1.5)--(2.5,1.5),red,EndArrow);
draw((2.5, 1.5)--(4.5, 1.5)--(4.5,0.5),red,EndArrow);
draw((4.5, 0.5)--(3.5, 0.5)--(3.5,2.5),red,EndArrow);
[/asy]
this will take us a total of 27 moves to the right. The second will finish in the following way:
[asy]
size(4cm);
path sq = (0,0)--(0,1)--(1,1)--(1,0)--cycle;
for (int i=0;i<5;++i) {
for (int j=0;j<6;++j) {
