f(1) &= 2 + 6 + 8 + 8 = 24 
f(9) &= 2(729) + 6(81) + 8(9) + 8 
&= 1458 + 486 + 72 + 8 = 2024 
f(5) &= 2(125) + 6(25) + 8(5) + 8 
&= 250 + 150 + 40 + 8 = \boxed{448}
\end{align*}

